item.text:
{
  "abilities": [
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "When Darius kills a champion with Noxian Guillotine, or applies 5 stacks on an enemy champion, he becomes empowered with Noxian Might for 5 seconds.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "The maximum-stack empowerment trigger requires an enemy champion; killing a champion with R is another trigger."
        },
        {
          "citations": [
            {
              "quote": "Hemorrhage does not apply to structures nor wards.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Darius' attacks and abilities have to deal damage to apply Hemorrhage.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Hemorrhage cannot be applied to/refreshed against invulnerable targets.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Hemorrhage can be applied to and refreshed against shielded targets.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Spell shield prevents Hemorrhage's application from abilities only.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Application requires damage and excludes structures, wards and invulnerable targets. Ordinary shields permit application and refresh; spell shields prevent application from abilities."
        },
        {
          "citations": [
            {
              "quote": "Hemorrhage deals 250% damage against monsters.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Hemorrhage deals increased damage against monsters."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Darius' attacks and damaging abilities cause enemies to bleed for physical damage over 5 seconds, stacking up to 5 times.",
              "source_id": "riot:P"
            },
            {
              "quote": "Hemorrhage: Deal physical damage to the target over a few seconds. For each stack, this damage is increased.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.bleed",
          "summary": "Eligible damaging attacks and abilities apply a stacking physical-damage bleed, up to five stacks."
        },
        {
          "citations": [
            {
              "quote": "Darius enrages and gains massive Attack Damage when his target reaches max stacks.",
              "source_id": "riot:P"
            },
            {
              "quote": "When Darius kills a champion with Noxian Guillotine, or applies 5 stacks on an enemy champion, he becomes empowered with Noxian Might for 5 seconds.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Noxian Might: Darius gains attack damage and always applies the maximum stacks of Hemorrhage.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.noxian_might",
          "summary": "Reaching five stacks on an enemy champion or killing a champion with R temporarily empowers Darius, granting attack damage and making eligible Hemorrhage applications apply maximum stacks."
        }
      ],
      "slot": "P",
      "unsupported_claims": [
        "Reaching five stacks on any enemy type grants Noxian Might.",
        "Every damaging ability hit applies Hemorrhage without exceptions.",
        "The unverified visual frames establish additional passive mechanics."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Enemies hit by the inner radius do not refresh the duration of or gain a stack of Hemorrhage.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Handle hits neither apply nor refresh Hemorrhage."
        },
        {
          "citations": [
            {
              "quote": "Against champions and large monsters hit, Darius heals for 17% – 51% (based on number of targets hit by the outer radius) of his missing health.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Healing scales with missing health and the number of eligible outer-radius targets hit, with the stated healing range providing a cap."
        },
        {
          "citations": [
            {
              "quote": "Darius can move during Decimate, but is unable to declare basic attacks or cast Apprehend or Noxian Guillotine.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Decimate will cancel if Darius enters stasis or uses Dash during the delay.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Darius can move during Q but cannot declare attacks or cast E or R; stasis or Dash during the delay cancels Q."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Darius winds up and swings his axe in a wide circle.",
              "source_id": "riot:Q"
            },
            {
              "quote": "Active: Darius briefly winds up to spin his axe in a circle while ghosted, dealing physical damage to enemies hit.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.circular_damage",
          "summary": "After a windup, Darius swings around himself, dealing physical damage."
        },
        {
          "citations": [
            {
              "quote": "Enemies struck by the blade take more damage than those struck by the handle.",
              "source_id": "riot:Q"
            },
            {
              "quote": "When Darius hits a champion with the blade, he applies a Hemorrhage stack and heals based on his missing health, multiplied by the number of champions hit up to 3. Enemies hit by the handle receive reduced damage and do not gain a Hemorrhage stack.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.blade_handle",
          "summary": "The outer blade deals more damage and can apply Hemorrhage; the inner handle deals reduced damage without applying Hemorrhage."
        },
        {
          "citations": [
            {
              "quote": "Darius heals based on enemy champions and large monsters hit by the blade.",
              "source_id": "riot:Q"
            },
            {
              "quote": "Against champions and large monsters hit, Darius heals for 17% – 51% (based on number of targets hit by the outer radius) of his missing health.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.heal",
          "summary": "Blade hits on enemy champions and large monsters heal Darius based on his missing health and the number of eligible targets hit."
        }
      ],
      "slot": "Q",
      "unsupported_claims": [
        "Handle hits heal Darius.",
        "Hitting any enemy type with the blade grants healing.",
        "Handle hits apply or refresh Hemorrhage."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "If this attack kills the target, half of Crippling Strike's cooldown is reduced and its mana cost is refunded.",
              "source_id": "wiki:W"
            },
            {
              "quote": "The cooldown reduction and mana refund will not trigger when killing jungle plants.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Killing the target with W refunds its mana cost and reduces its cooldown, except when killing jungle plants."
        },
        {
          "citations": [
            {
              "quote": "Active: Darius empowers his next basic attack within 4 seconds to have an uncancellable windup, gain 25 bonus range, deal bonus physical damage and slow the target by 90% for 1 second. This damage is affected by critical strike modifiers.",
              "source_id": "wiki:W"
            },
            {
              "quote": "The attack's animation can be cancelled by casting Decimate, but the attack will still land.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "The empowered attack gains range and an uncancellable windup, and its damage is affected by critical strike modifiers. Casting Q can cancel its animation while the attack still lands."
        },
        {
          "citations": [
            {
              "quote": "Crippling Strike deals basic damage but will also trigger spell effects by also being tagged as spell damage.",
              "source_id": "wiki:W"
            },
            {
              "quote": "Spell shields will negate all effects of Crippling Strike, including the damage of the basic attack itself.(unexpected)",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "W also triggers spell effects, and the Wiki explicitly reports that spell shields negate the entire empowered attack, including its basic-attack damage."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Active: Darius' next basic attack within a few seconds deals increased physical damage and slows the target.",
              "source_id": "wiki:W"
            },
            {
              "quote": "Darius's next attack strikes an enemy's crucial artery. As they bleed out, their Move Speed is slowed.",
              "source_id": "riot:W"
            }
          ],
          "id": "W.empowered_attack",
          "summary": "Empowers Darius's next basic attack to deal increased physical damage and slow its target."
        },
        {
          "citations": [
            {
              "quote": "Crippling Strike resets Darius' basic attack timer.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.attack_reset",
          "summary": "Resets Darius's basic attack timer."
        }
      ],
      "slot": "W",
      "unsupported_claims": [
        "W roots or stuns its target.",
        "W kills fully reset its cooldown.",
        "W's slow persists for the entire Hemorrhage duration."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Upon arrival, they rebound 150 units off of him, remaining airborne and becoming slowed by 40% for 1 second.",
              "source_id": "wiki:E"
            },
            {
              "quote": "The slow duration starts as soon as the target rebounds off of Darius.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Pulled targets rebound away from Darius while remaining airborne; the slow begins when they rebound."
        },
        {
          "citations": [
            {
              "quote": "PENDING FOR TEST:: The rebound location is determined when the target reaches Darius' location.",
              "source_id": "wiki:E"
            },
            {
              "quote": "PENDING FOR TEST:: There is no stun applied for the same duration of the airborne, meaning brittle cannot extend the disable duration.",
              "source_id": "wiki:E"
            }
          ],
          "status": "uncertain",
          "summary": "The rebound-location calculation and absence of a simultaneous stun, including the claimed brittle interaction, are pending testing."
        },
        {
          "citations": [
            {
              "quote": "After the pull, Darius will attempt to basic attack the closest pulled target, prioritizing enemy champions.",
              "source_id": "wiki:E"
            },
            {
              "quote": "The armor penetration stacks multiplicatively with other forms of percentage armor penetration.",
              "source_id": "wiki:E"
            },
            {
              "quote": "This ability will cast from wherever the caster is at the end of the cast time.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "After pulling, Darius attempts an attack with champion priority. The passive penetration stacks multiplicatively with other percentage penetration, and the active originates from his position at cast completion."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Darius hones his axe, passively causing his physical damage to ignore a percentage of his target's Armor.",
              "source_id": "riot:E"
            },
            {
              "quote": "Passive: Darius gains armor penetration.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.armor_penetration",
          "summary": "Passively grants percentage armor penetration for Darius's physical damage."
        },
        {
          "citations": [
            {
              "quote": "When activated, Darius sweeps up his enemies with his axe's hook and pulls them to him.",
              "source_id": "riot:E"
            },
            {
              "quote": "Active: Darius sweeps in a cone in the target direction, slowing and pulling enemies hit towards him.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.pull_slow",
          "summary": "Sweeps a cone in front of Darius, pulling enemies hit toward him and slowing them."
        }
      ],
      "slot": "E",
      "unsupported_claims": [
        "E directly deals damage or applies Hemorrhage.",
        "E reduces the target's armor for allies.",
        "The pending-test rebound and brittle claims are confirmed mechanics."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "If the target dies within 0.15 seconds after being hit by Noxian Guillotine, Darius fears nearby minions and monsters for 3 seconds, during which they are gradually slowed by up to 99% over the duration. He can also recast the ability within 20 seconds at no cost, which refreshes on further successful executions.",
              "source_id": "wiki:R"
            },
            {
              "quote": "At max rank, Noxian Guillotine permanently resets its cooldown if the target dies very briefly afterwards.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "A target death within the stated brief post-hit window qualifies for reuse and fears and slows nearby minions and monsters. Earlier ranks provide a temporary free recast window; maximum rank permanently resets the cooldown."
        },
        {
          "citations": [
            {
              "quote": "Noxian Guillotine will not reset nor trigger Noxian Might if used to kill a clone or a target protected by resurrection.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Noxian Guillotine will reset but not trigger Noxian Might if it finishes off a target that is in a zombie state.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Clone and resurrection-protected kills do not grant a reset or Noxian Might. Finishing a zombie-state target grants a reset without Noxian Might."
        },
        {
          "citations": [
            {
              "quote": "Noxian Guillotine applies Hemorrhage after the damage.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "R applies its Hemorrhage stack after dealing damage."
        },
        {
          "citations": [
            {
              "quote": "The ability is disabled while grounded or rooted even if Darius is in the range in which he does not leap.",
              "source_id": "wiki:R"
            },
            {
              "quote": "If the target becomes untargetable, dies, or is too far away or no longer in sight during the cast time, this ability will cancel but does not go on cooldown nor pay its cost (if applicable).",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Grounding and roots prevent casting. Losing a valid, visible target within range during the cast cancels R without spending its cost or starting its cooldown."
        },
        {
          "citations": [
            {
              "quote": "Darius will only leap towards the target if it is at range, or leap backwards if it is very close.",
              "source_id": "wiki:R"
            },
            {
              "quote": "This leap can pass very thin terrain and will otherwise not be able to. In any case, Darius will still hit the target.[1]",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Leap movement depends on target distance and can cross very thin terrain; inability to cross other terrain does not itself prevent the hit."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Darius leaps to an enemy champion and strikes a lethal blow, dealing true damage.",
              "source_id": "riot:R"
            },
            {
              "quote": "Active: Darius attempts to execute the target enemy champion, leaping towards them to deal true damage",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.true_damage",
          "summary": "Targets an enemy champion with a leap strike that deals true damage."
        },
        {
          "citations": [
            {
              "quote": "This damage is increased for each stack of Hemorrhage on the target.",
              "source_id": "riot:R"
            },
            {
              "quote": "dealing true damage based on the target's current Hemorrhage stacks.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.hemorrhage_scaling",
          "summary": "Deals more damage for each Hemorrhage stack already on the target."
        },
        {
          "citations": [
            {
              "quote": "If Noxian Guillotine is a killing blow, its cooldown is refreshed for a brief duration.",
              "source_id": "riot:R"
            },
            {
              "quote": "If the target dies very briefly afterwards, Noxian Guillotine's cooldown is temporarily reset",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.kill_reuse",
          "summary": "A qualifying kill allows Darius to use R again, generally through a temporary recast window."
        }
      ],
      "slot": "R",
      "unsupported_claims": [
        "R guarantees a kill regardless of target health.",
        "R requires five Hemorrhage stacks to cast.",
        "Every target death grants both a reset and Noxian Might.",
        "R has an unrestricted terrain-crossing leap."
      ]
    }
  ]
}
